/* EARTHUS V2 — truth-first real Earth runtime. */
import { initViewer, viewer as sharedViewer, scene as sharedScene, gibsProvider, setAmbientView } from '../../js/viewer.js';
import { API } from '../../js/config.js';
import { buildCloudShadowAlpha } from '../../js/cloud-shadow.js';
import { Gk2aCthReliefRuntime } from './gk2a-cth-relief.js';
import { GfsCloudVolumeRuntime } from './gfs-cloud-volume.js';

const TOPO_BATHY_URL='https://elevation3d.arcgis.com/arcgis/rest/services/WorldElevation3D/TopoBathy3D/ImageServer';
const LAND_TERRAIN_URL='https://elevation3d.arcgis.com/arcgis/rest/services/WorldElevation3D/Terrain3D/ImageServer';
const ESRI_IMAGERY='https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';
const NASA_GIBS_4326_WMS='https://gibs.earthdata.nasa.gov/wms/epsg4326/best/wms.cgi';
const CLOUD_SHELL_DISPLAY_HEIGHT_M=12_000; // visual placement only, never observed CTH
const CLOUD_REFRESH_MS=20*60_000;
const TRENCH=Object.freeze({lon:142.20,lat:11.35});
const POLAR_SOURCE=Object.freeze({id:'GLOBAL_GEOGRAPHIC_BASE',epsg:'EPSG:4326',layer:'BlueMarble_NextGeneration',truthClass:'NASA_GIBS_GEOGRAPHIC_IMAGERY_ONLY'});

let viewer=null,scene=null,terrainProvider=null;
let terrainTruth='UNINITIALIZED',waterTruth='NO_WATER_MASK',polarTruth='NASA_GIBS_GEOGRAPHIC_IMAGERY_ONLY',activeMode='EARTH',cloudFidelity='SHELL';
let polarBaseLayer=null,baseLayer=null,detailLayer=null,cityLightsLayer=null,cloudShadowLayer=null;
let cloudShell=null,cloudMeta=null,cloudTimer=null,cloudGeneration=0,cthRelief=null,cthMeta=null,cloudVolume=null,volumeMeta=null;
let lastVolumeError=null,lastCthError=null;
let trenchSample=null,sourceBadge=null,underwaterRestore=null,waterRestore=null;
let featureRequestHandler=null,earthClickHandler=null,cameraReadoutRemove=null,cameraDetailRemove=null;

const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const smooth=(a,b,x)=>{const t=clamp((x-a)/Math.max(1e-9,b-a));return t*t*(3-2*t)};
const progress=(task,stage,value,provider)=>{try{task?.update?.({stage,progress:value,provider})}catch(_){}};
const announce=message=>document.dispatchEvent(new CustomEvent('earthus:v2-real-earth-notice',{detail:{message}}));

function badge(extra=''){
  if(!sourceBadge?.isConnected){sourceBadge=document.createElement('div');sourceBadge.id='earthusV2RealSources';sourceBadge.setAttribute('aria-live','polite');Object.assign(sourceBadge.style,{position:'fixed',left:'18px',bottom:'76px',zIndex:'4',maxWidth:'min(780px,calc(100vw - 36px))',padding:'6px 9px',border:'1px solid rgba(188,220,238,.11)',borderRadius:'10px',background:'rgba(2,8,12,.54)',backdropFilter:'blur(12px)',color:'#78909c',font:'8px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace',pointerEvents:'none'});document.body.append(sourceBadge)}
  const t=terrainTruth==='ESRI_TOPOBATHY3D'?'TERRAIN/BATHY: Esri TopoBathy3D':terrainTruth==='ESRI_TERRAIN3D'?'TERRAIN: Esri Terrain3D · bathymetry unavailable':'TERRAIN: ellipsoid fallback';
  const w=waterTruth==='PROVIDER_WATER_MASK'?'WATER: provider mask + reflective waves':'WATER: provider mask unavailable';
  const p=polarTruth==='NASA_GIBS_GEOGRAPHIC_IMAGERY_ONLY'?'POLAR: NASA GIBS EPSG4326 imagery-only':'POLAR: unavailable';
  const c=cloudMeta?.time?`CLOUD L0: NOAA GMGSI ${cloudMeta.time}`:'CLOUD L0: loading / unavailable',r=cthMeta?.validAt?` · L1 GK2A CTH ${cthMeta.validAt}`:'',v=volumeMeta?.cloudState?.validAt?` · L2 GFS VOLUME ${volumeMeta.cloudState.validAt}`:'';
  sourceBadge.textContent=`${t} · ${w} · ${p} · ${c}${r}${v} · ACTIVE ${cloudFidelity}${extra?` · ${extra}`:''}`;
}
function sunFixedAt(iso){const time=Cesium.JulianDate.fromIso8601(iso),inertial=Cesium.Simon1994PlanetaryPositions.computeSunPositionInEarthInertialFrame(time,new Cesium.Cartesian3());let m=Cesium.Transforms.computeIcrfToFixedMatrix(time,new Cesium.Matrix3());if(!Cesium.defined(m))m=Cesium.Transforms.computeTemeToPseudoFixedMatrix(time,new Cesium.Matrix3());const fixed=Cesium.Matrix3.multiplyByVector(m,inertial,new Cesium.Cartesian3());Cesium.Cartesian3.normalize(fixed,fixed);return[fixed.x,fixed.y,fixed.z]}
async function imageFromBlob(blob){const url=URL.createObjectURL(blob);try{const image=new Image();image.crossOrigin='anonymous';await new Promise((ok,no)=>{image.onload=ok;image.onerror=()=>no(new Error('CLOUD_IMAGE_DECODE_FAILED'));image.src=url});return image}finally{URL.revokeObjectURL(url)}}
function normalizeCloud(image,meta){const cv=document.createElement('canvas');cv.width=image.naturalWidth||image.width;cv.height=image.naturalHeight||image.height;const cx=cv.getContext('2d',{willReadFrequently:true});cx.drawImage(image,0,0);const px=cx.getImageData(0,0,cv.width,cv.height),d=px.data;if(meta.format==='la8')for(let i=0;i<d.length;i+=4){const l=90+d[i]*165/255;d[i]=d[i+1]=d[i+2]=Math.round(l);d[i+3]=Math.round(255*Math.pow(d[i+3]/255,.78))}else for(let i=0;i<d.length;i+=4){const a=Math.round(255*Math.pow(d[i]/255,.78));d[i]=d[i+1]=d[i+2]=255;d[i+3]=a}cx.putImageData(px,0,0);return{canvas:cv,rgba:px.data}}
function shadowCanvas(rgba,w,h,meta){const r=buildCloudShadowAlpha({rgba,sourceWidth:w,sourceHeight:h,north:Cesium.Math.toRadians(meta.north),south:Cesium.Math.toRadians(meta.south),sun:sunFixedAt(meta.time)}),a=document.createElement('canvas');a.width=r.width;a.height=r.height;const ac=a.getContext('2d'),im=ac.createImageData(r.width,r.height);for(let i=0;i<r.alpha.length;i++){const p=i*4;im.data[p]=im.data[p+1]=im.data[p+2]=0;im.data[p+3]=Math.round(r.alpha[i]*.32)}ac.putImageData(im,0,0);const b=document.createElement('canvas');b.width=a.width;b.height=a.height;const bc=b.getContext('2d');bc.filter='blur(1.5px)';bc.drawImage(a,0,0);return b}
function removeCloud(){if(cloudShell){try{scene.primitives.remove(cloudShell)}catch(_){}cloudShell=null}if(cloudShadowLayer){try{viewer.imageryLayers.remove(cloudShadowLayer,true)}catch(_){}cloudShadowLayer=null}}
function addCloudShell(canvas,meta){const rect=Cesium.Rectangle.fromDegrees(-180,meta.south,180,meta.north),material=Cesium.Material.fromType('Image',{image:canvas,repeat:new Cesium.Cartesian2(1,1),color:Cesium.Color.WHITE.withAlpha(.92),transparent:true}),p=new Cesium.Primitive({geometryInstances:new Cesium.GeometryInstance({geometry:new Cesium.RectangleGeometry({rectangle:rect,height:CLOUD_SHELL_DISPLAY_HEIGHT_M,granularity:Cesium.Math.toRadians(1),vertexFormat:Cesium.EllipsoidSurfaceAppearance.VERTEX_FORMAT})}),appearance:new Cesium.EllipsoidSurfaceAppearance({aboveGround:true,faceForward:true,translucent:true,material}),asynchronous:false,show:activeMode==='EARTH'&&cloudFidelity==='SHELL'});scene.primitives.add(p);return p}
function addShadow(canvas,meta){const provider=new Cesium.SingleTileImageryProvider({url:canvas.toDataURL('image/png'),rectangle:Cesium.Rectangle.fromDegrees(-180,meta.south,180,meta.north),tileWidth:canvas.width,tileHeight:canvas.height,credit:meta.credit||'NOAA NESDIS GMGSI'}),layer=viewer.imageryLayers.addImageryProvider(provider);layer.alpha=.24;layer.show=activeMode==='EARTH';return layer}
function setObservedShadow(alpha=.24,show=true){if(!cloudShadowLayer)return;cloudShadowLayer.alpha=alpha;cloudShadowLayer.show=!!show&&activeMode==='EARTH'}
function syncPhysicalWater(){if(!scene?.globe)return false;if(waterRestore===null)waterRestore=scene.globe.showWaterEffect;const supported=terrainProvider?.hasWaterMask===true;scene.globe.showWaterEffect=supported;waterTruth=supported?'PROVIDER_WATER_MASK':'NO_WATER_MASK';return supported}
async function loadCloud({force=false}={}){const generation=++cloudGeneration;try{const mr=await fetch(`${API.CLOUDS}/meta.json`,{cache:'no-cache'});if(!mr.ok)throw new Error(`GMGSI_META_${mr.status}`);const meta=await mr.json();if(!meta?.time||!Number.isFinite(Number(meta.south))||!Number.isFinite(Number(meta.north)))throw new Error('GMGSI_META_INVALID');if(!force&&cloudMeta?.time===meta.time&&cloudShell)return cloudMeta;const ir=await fetch(`${API.CLOUDS}/global.png?t=${encodeURIComponent(meta.time)}`,{cache:'no-cache'});if(!ir.ok)throw new Error(`GMGSI_IMAGE_${ir.status}`);const normalized=normalizeCloud(await imageFromBlob(await ir.blob()),meta);if(generation!==cloudGeneration)return cloudMeta;const shadow=shadowCanvas(normalized.rgba,normalized.canvas.width,normalized.canvas.height,meta);removeCloud();cloudShadowLayer=addShadow(shadow,meta);cloudShell=addCloudShell(normalized.canvas,meta);cloudMeta=Object.freeze({time:meta.time,source:'NOAA_NESDIS_GMGSI',truthClass:'OBSERVED_2D_SHELL',heightClass:'DISPLAY_ONLY_NOT_CTH'});badge();scene.requestRender();return cloudMeta}catch(error){console.warn('[v2-real-earth/cloud]',error?.message||error);badge('cloud L0 unavailable');return null}}
function scheduleCloud(){clearTimeout(cloudTimer);cloudTimer=setTimeout(async()=>{if(document.visibilityState==='visible')await loadCloud({force:true});scheduleCloud()},CLOUD_REFRESH_MS)}
function hideCloud3d(){cloudVolume?.hide();cthRelief?.hide();cloudFidelity='SHELL';if(cloudShell)cloudShell.show=activeMode==='EARTH';setObservedShadow(.24,true)}
async function showBestCloud3d(){lastVolumeError=null;lastCthError=null;if(!cloudVolume)cloudVolume=new GfsCloudVolumeRuntime({viewer,Cesium});try{volumeMeta=await cloudVolume.show();cthRelief?.hide();cloudFidelity='VOLUME';if(cloudShell)cloudShell.show=false;setObservedShadow(.13,true);const a=volumeMeta.anchor;viewer.camera.flyTo({destination:Cesium.Cartesian3.fromDegrees(a.longitudeDeg,a.latitudeDeg-5.5,1_650_000),orientation:{heading:0,pitch:Cesium.Math.toRadians(-52),roll:0},duration:1.15});badge('VOLUME: GFS TCDC + HGT · step-aware optical alpha');announce(`NOAA GFS 실제 수직 구름 Volume · ${volumeMeta.cloudState.validAt}`);return 'VOLUME'}catch(error){lastVolumeError=String(error?.message||error);cloudVolume?.hide();console.warn('[v2-real-earth/volume]',lastVolumeError)}if(!cthRelief)cthRelief=new Gk2aCthReliefRuntime({viewer,Cesium});try{cthMeta=await cthRelief.show();cloudFidelity='CTH_RELIEF';if(cloudShell)cloudShell.show=false;setObservedShadow(.14,true);viewer.camera.flyTo({destination:Cesium.Cartesian3.fromDegrees(132,26,1_850_000),orientation:{heading:0,pitch:Cesium.Math.toRadians(-55),roll:0},duration:1.15});badge('CTH: observed GMGSI masked by actual CTH altitude bands · smooth display interpolation');announce(`천리안2A 실제 운정고도 고도대 3D · ${cthMeta.validAt}`);return 'CTH_RELIEF'}catch(error){lastCthError=String(error?.message||error);cthRelief?.hide();console.warn('[v2-real-earth/cth]',lastCthError)}cloudFidelity='SHELL';if(cloudShell)cloudShell.show=true;setObservedShadow(.24,true);badge(`3D cloud fallback · CTH ${lastCthError||'unknown'}`);announce('실제 3D 구름 산출물 렌더가 실패해 NOAA 관측 Shell로 유지합니다.');return 'SHELL'}

async function installTerrain(){try{terrainProvider=await Cesium.ArcGISTiledElevationTerrainProvider.fromUrl(TOPO_BATHY_URL);viewer.terrainProvider=terrainProvider;terrainTruth='ESRI_TOPOBATHY3D';syncPhysicalWater()}catch(error){console.warn('[v2-real-earth/terrain] TopoBathy3D:',error?.message||error);try{terrainProvider=await Cesium.ArcGISTiledElevationTerrainProvider.fromUrl(LAND_TERRAIN_URL);viewer.terrainProvider=terrainProvider;terrainTruth='ESRI_TERRAIN3D';syncPhysicalWater()}catch(e){console.warn('[v2-real-earth/terrain] Terrain3D:',e?.message||e);terrainProvider=viewer.terrainProvider;terrainTruth='ELLIPSOID_FALLBACK';syncPhysicalWater()}}badge();scene.requestRender();return terrainTruth}
function updateImageryForView(){if(!viewer)return;const h=viewer.camera.positionCartographic?.height??24_000_000;if(activeMode==='UNDERWATER'){if(polarBaseLayer)polarBaseLayer.alpha=.6;if(baseLayer)baseLayer.alpha=.82;if(detailLayer)detailLayer.alpha=.02;if(cityLightsLayer)cityLightsLayer.show=false;return}if(activeMode==='TRENCH'){if(polarBaseLayer)polarBaseLayer.alpha=.76;if(baseLayer)baseLayer.alpha=.94;if(detailLayer)detailLayer.alpha=.025;if(cityLightsLayer)cityLightsLayer.show=false;return}const d=.035+.965*(1-smooth(1_500_000,8_500_000,h));if(polarBaseLayer)polarBaseLayer.alpha=1;if(baseLayer)baseLayer.alpha=1;if(detailLayer)detailLayer.alpha=d;if(cityLightsLayer)cityLightsLayer.show=true}
function installImagery(){polarBaseLayer=viewer.imageryLayers.addImageryProvider(new Cesium.WebMapServiceImageryProvider({url:NASA_GIBS_4326_WMS,layers:'BlueMarble_NextGeneration',parameters:{transparent:'false',format:'image/jpeg'},tilingScheme:new Cesium.GeographicTilingScheme(),maximumLevel:2,credit:'NASA GIBS'}));polarBaseLayer.dayAlpha=1;polarBaseLayer.nightAlpha=.1;baseLayer=viewer.imageryLayers.addImageryProvider(gibsProvider({layer:'BlueMarble_ShadedRelief_Bathymetry',level:8,ext:'jpeg'}));baseLayer.dayAlpha=1;baseLayer.nightAlpha=.1;baseLayer.brightness=.98;baseLayer.saturation=.94;detailLayer=viewer.imageryLayers.addImageryProvider(new Cesium.UrlTemplateImageryProvider({url:ESRI_IMAGERY,maximumLevel:19,credit:'Powered by Esri · Source: Esri, Vantor, Earthstar Geographics, and the GIS User Community'}));detailLayer.brightness=.97;detailLayer.contrast=1.02;detailLayer.saturation=.94;cityLightsLayer=viewer.imageryLayers.addImageryProvider(gibsProvider({layer:'VIIRS_CityLights_2012',level:8,ext:'jpeg'}));cityLightsLayer.dayAlpha=0;cityLightsLayer.nightAlpha=.76;cityLightsLayer.brightness=1.1;polarTruth='NASA_GIBS_GEOGRAPHIC_IMAGERY_ONLY';cameraDetailRemove?.();cameraDetailRemove=viewer.camera.changed.addEventListener(updateImageryForView);updateImageryForView()}
function removeTrench(){trenchSample=null}
function restoreUnderwater(){if(!underwaterRestore||!scene)return;const r=underwaterRestore,cc=scene.screenSpaceCameraController,g=scene.globe,t=g.translucency;cc.enableCollisionDetection=r.collision;t.enabled=r.translucencyEnabled;t.frontFaceAlpha=r.frontFaceAlpha;t.backFaceAlpha=r.backFaceAlpha;t.frontFaceAlphaByDistance=r.frontFaceAlphaByDistance;t.backFaceAlphaByDistance=r.backFaceAlphaByDistance;t.rectangle=r.rectangle;g.undergroundColor=r.undergroundColor;g.undergroundColorAlphaByDistance=r.undergroundColorAlphaByDistance;g.backFaceCulling=r.backFaceCulling;g.showSkirts=r.showSkirts;g.enableLighting=r.enableLighting;g.showGroundAtmosphere=r.showGroundAtmosphere;scene.skyAtmosphere.show=r.skyAtmosphereShow;scene.sun.show=r.sunShow;scene.fog.enabled=r.fogEnabled;scene.backgroundColor=r.backgroundColor;globalThis.__earthusSkyPanorama?.show?.();underwaterRestore=null}
function prepareUnderwater(){restoreUnderwater();const cc=scene.screenSpaceCameraController,g=scene.globe,t=g.translucency;underwaterRestore={collision:cc.enableCollisionDetection,translucencyEnabled:t.enabled,frontFaceAlpha:t.frontFaceAlpha,backFaceAlpha:t.backFaceAlpha,frontFaceAlphaByDistance:t.frontFaceAlphaByDistance,backFaceAlphaByDistance:t.backFaceAlphaByDistance,rectangle:t.rectangle,undergroundColor:g.undergroundColor,undergroundColorAlphaByDistance:g.undergroundColorAlphaByDistance,backFaceCulling:g.backFaceCulling,showSkirts:g.showSkirts,enableLighting:g.enableLighting,showGroundAtmosphere:g.showGroundAtmosphere,skyAtmosphereShow:scene.skyAtmosphere.show,sunShow:scene.sun.show,fogEnabled:scene.fog.enabled,backgroundColor:scene.backgroundColor};cc.enableCollisionDetection=false;t.enabled=true;t.frontFaceAlpha=1;t.backFaceAlpha=1;t.frontFaceAlphaByDistance=undefined;t.backFaceAlphaByDistance=undefined;t.rectangle=Cesium.Rectangle.MAX_VALUE;g.backFaceCulling=false;g.showSkirts=false;g.undergroundColor=undefined;g.undergroundColorAlphaByDistance=undefined;g.enableLighting=false;g.showGroundAtmosphere=false;scene.skyAtmosphere.show=false;scene.sun.show=false;scene.fog.enabled=false;scene.backgroundColor=Cesium.Color.fromCssColorString('#01080d');globalThis.__earthusSkyPanorama?.hide?.()}
async function sampleDepth(){if(terrainTruth!=='ESRI_TOPOBATHY3D'||!terrainProvider)return null;const p=Cesium.Cartographic.fromDegrees(TRENCH.lon,TRENCH.lat);try{let s=null;if(typeof Cesium.sampleTerrainMostDetailed==='function')try{[s]=await Cesium.sampleTerrainMostDetailed(terrainProvider,[p])}catch(_){}if(!s&&typeof Cesium.sampleTerrain==='function')[s]=await Cesium.sampleTerrain(terrainProvider,12,[p]);const h=Number(s?.height);return Number.isFinite(h)?Object.freeze({heightM:h,depthM:h<0?-h:0,source:'ESRI_TOPOBATHY3D_PROVIDER_SAMPLE'}):null}catch(e){console.warn('[v2-real-earth/trench-sample]',e?.message||e);return null}}
async function enterTrench(){hideCloud3d();if(terrainTruth!=='ESRI_TOPOBATHY3D'){announce('실제 Bathymetry Provider가 준비되지 않아 해구 모드를 열지 않았습니다.');badge('TRENCH blocked');return false}restoreUnderwater();trenchSample=await sampleDepth();activeMode='TRENCH';if(cloudShell)cloudShell.show=false;setObservedShadow(0,false);scene.globe.maximumScreenSpaceError=.9;scene.globe.enableLighting=false;scene.globe.showGroundAtmosphere=false;scene.skyAtmosphere.show=false;scene.sun.show=false;globalThis.__earthusSkyPanorama?.hide?.();scene.screenSpaceCameraController.enableTilt=true;scene.screenSpaceCameraController.enableLook=false;updateImageryForView();const cameraHeight=Math.min(140_000,Math.max(70_000,(trenchSample?.depthM||10_000)*9));viewer.camera.flyTo({destination:Cesium.Cartesian3.fromDegrees(TRENCH.lon,TRENCH.lat-.38,cameraHeight),orientation:{heading:0,pitch:Cesium.Math.toRadians(-72),roll:0},duration:1.25});const sample=trenchSample?.depthM>0?`PROVIDER SAMPLE ${Math.round(trenchSample.depthM).toLocaleString()}m below 0m`:'PROVIDER SAMPLE unavailable';badge(`TRENCH: real TopoBathy surface · daylight-neutral analytic view · ${sample}`);announce('실제 TopoBathy3D 해저지형을 태양광 암화 없이 직접 표시합니다.');scene.requestRender();return true}
async function enterUnderwater(){hideCloud3d();if(terrainTruth!=='ESRI_TOPOBATHY3D'){announce('실제 Bathymetry Provider가 없어 수중 카메라를 열지 않았습니다.');badge('UNDERWATER blocked');return false}const sample=await sampleDepth();if(!(sample?.depthM>1200)){announce('검증 가능한 실제 해저 수심을 읽지 못해 수중 카메라를 열지 않았습니다.');badge('UNDERWATER blocked · provider sample unavailable');return false}trenchSample=sample;activeMode='UNDERWATER';if(cloudShell)cloudShell.show=false;setObservedShadow(0,false);prepareUnderwater();scene.globe.maximumScreenSpaceError=.72;scene.screenSpaceCameraController.enableTilt=true;scene.screenSpaceCameraController.enableLook=true;updateImageryForView();const cameraDepth=Math.min(6500,Math.max(1200,sample.depthM-4000));viewer.camera.flyTo({destination:Cesium.Cartesian3.fromDegrees(TRENCH.lon,TRENCH.lat,-cameraDepth),orientation:{heading:0,pitch:Cesium.Math.toRadians(-78),roll:0},duration:1.35});badge(`UNDERWATER: real bathymetry · camera ${Math.round(cameraDepth).toLocaleString()}m below 0m · seafloor sample ${Math.round(sample.depthM).toLocaleString()}m`);announce('실제 Bathymetry 해저를 아래로 내려다봅니다 · 불투명 지하 Terrain 경로를 사용합니다.');scene.requestRender();return true}
function enterEarth(){restoreUnderwater();activeMode='EARTH';hideCloud3d();removeTrench();scene.globe.maximumScreenSpaceError=2;scene.globe.enableLighting=true;scene.globe.showGroundAtmosphere=true;scene.skyAtmosphere.show=true;scene.sun.show=true;scene.fog.enabled=false;globalThis.__earthusSkyPanorama?.show?.();scene.screenSpaceCameraController.enableTilt=false;scene.screenSpaceCameraController.enableLook=false;updateImageryForView();setAmbientView(127,25,.52);badge();scene.requestRender()}
function installBridge(){if(featureRequestHandler)return;featureRequestHandler=async event=>{const{menu,feature}=event.detail||{};if(menu==='WEATHER'&&feature==='Clouds'){enterEarth();await loadCloud({force:false});await showBestCloud3d();return}if(menu==='OCEAN'&&feature==='Bathymetry / Trench'){await enterTrench();return}if(menu==='OCEAN'&&feature==='Underwater'){await enterUnderwater();return}if(activeMode!=='EARTH'||cloudFidelity!=='SHELL')enterEarth()};earthClickHandler=event=>{if(event.target?.closest?.('#home,[data-menu="EARTH"]'))enterEarth()};document.addEventListener('earthus:v2-feature-request',featureRequestHandler);document.addEventListener('click',earthClickHandler,true)}
function installReadout(){cameraReadoutRemove?.();cameraReadoutRemove=scene.postRender.addEventListener(()=>{const p=viewer.camera.positionCartographic;if(!p)return;const la=Cesium.Math.toDegrees(p.latitude),lo=Cesium.Math.toDegrees(p.longitude),c=document.getElementById('coord'),a=document.getElementById('alt');if(c)c.textContent=`${Math.abs(la).toFixed(1)}°${la>=0?'N':'S'} · ${Math.abs(lo).toFixed(1)}°${lo>=0?'E':'W'}`;if(a)a.textContent=`ALT ${Math.round(p.height/1000).toLocaleString()} km`})}

export async function bootRealLivingEarth({containerId='g',task=null}={}){if(!globalThis.Cesium)throw new Error('CESIUM_RUNTIME_UNAVAILABLE');progress(task,'viewer',30,'EARTHUS canonical Cesium viewer');initViewer(containerId);viewer=sharedViewer;scene=sharedScene;if(!viewer||!scene)throw new Error('CANONICAL_VIEWER_INIT_FAILED');scene.globe.depthTestAgainstTerrain=true;scene.globe.enableLighting=true;scene.globe.showGroundAtmosphere=true;if('dynamicAtmosphereLighting'in scene.globe)scene.globe.dynamicAtmosphereLighting=true;if('dynamicAtmosphereLightingFromSun'in scene.globe)scene.globe.dynamicAtmosphereLightingFromSun=true;if('highDynamicRange'in scene)scene.highDynamicRange=true;scene.sun.show=true;scene.moon.show=false;scene.fog.enabled=false;viewer.clock.shouldAnimate=false;viewer.clock.currentTime=Cesium.JulianDate.now();progress(task,'imagery',44,'NASA GIBS geographic + WebMercator/Esri detail');installImagery();progress(task,'terrain',58,'Esri WorldElevation3D TopoBathy3D');await installTerrain();setAmbientView(127,25,.52);installReadout();installBridge();progress(task,'cloud',72,'NOAA NESDIS GMGSI observed cloud shell');loadCloud().finally(()=>scene.requestRender());scheduleCloud();badge();scene.requestRender();return Object.freeze({viewer,scene,terrainTruth,polarTruth:()=>polarTruth,polarSources:()=>Object.freeze([POLAR_SOURCE]),waterTruth:()=>waterTruth,cloudTruth:()=>cloudMeta,cthTruth:()=>cthMeta,volumeTruth:()=>volumeMeta,cloudFidelity:()=>cloudFidelity,cloudDiagnostics:()=>Object.freeze({volume:lastVolumeError,cth:lastCthError}),enterEarth,enterTrench,enterUnderwater,showBestCloud3d,refreshClouds:()=>loadCloud({force:true}),trenchSample:()=>trenchSample,dispose(){clearTimeout(cloudTimer);cloudGeneration++;restoreUnderwater();cloudVolume?.dispose();cloudVolume=null;volumeMeta=null;cthRelief?.dispose();cthRelief=null;cthMeta=null;lastVolumeError=lastCthError=null;removeCloud();removeTrench();cameraReadoutRemove?.();cameraReadoutRemove=null;cameraDetailRemove?.();cameraDetailRemove=null;if(featureRequestHandler){document.removeEventListener('earthus:v2-feature-request',featureRequestHandler);featureRequestHandler=null}if(earthClickHandler){document.removeEventListener('click',earthClickHandler,true);earthClickHandler=null}for(const layer of[cityLightsLayer,detailLayer,baseLayer,polarBaseLayer]){if(!layer||!viewer?.imageryLayers)continue;try{viewer.imageryLayers.remove(layer,true)}catch(_){}}if(waterRestore!==null&&scene?.globe)scene.globe.showWaterEffect=waterRestore;waterRestore=null;polarBaseLayer=baseLayer=detailLayer=cityLightsLayer=null;sourceBadge?.remove?.();sourceBadge=null;waterTruth='NO_WATER_MASK';polarTruth='NASA_GIBS_GEOGRAPHIC_IMAGERY_ONLY';activeMode='EARTH';cloudFidelity='SHELL'}})}